/* Courses: original coaching content. Each lesson has key points and drills to practice it. */
var COURSES = [
  { id: 'shot', title: 'Shooting Mechanics Reset', area: 'Shooting', color: '#ff913d', blurb: 'Rebuild a repeatable jumper from the feet up.', lessons: [
    { t: 'Start at the rim', m: 12, pts: ['Shoot one-handed 3 feet from the rim before anything else. It strips the shot down to the release.', 'Ball sits on the finger pads with a gap under the palm.', 'Elbow sits under the ball, not flared out. Your wrist makes a tray.', 'Hold the follow-through until the ball hits the rim: fingers in the cup.'], drills: ['d-form-close'] },
    { t: 'Feet and base', m: 10, pts: ['Feet about shoulder width, shooting foot slightly ahead, toes pointed at the rim or slightly turned.', 'Bend at the knees and hips, not just the knees. Power comes from the legs.', 'Land where you took off. Drifting forward or sideways shows a balance problem.'], drills: ['d-closeout-footwork'] },
    { t: 'The one-motion release', m: 12, pts: ['Ball goes up as your legs go up: one smooth motion, no hitch at the top.', 'Set point: ball above your forehead so you can see the rim under it.', 'Guide hand stays on the side and comes off cleanly. It never pushes the ball.'], drills: ['d-form-close', 'd-gather-types'] },
    { t: 'Arc and aim', m: 8, pts: ['Aim for the back half of the rim with a high arc (around 45 degrees). Flat shots need perfect accuracy.', 'Pick a target and keep your eyes on it from catch to the ball reaching the rim.', 'Track misses: short or long is legs, left or right is elbow or guide hand.'], drills: ['d-form-close'] },
    { t: 'Catch-and-shoot rhythm', m: 12, pts: ['Hands ready and knees bent before the catch.', 'Inside foot first when moving laterally (1-2), or hop to square fast.', 'Catch it in your shot pocket: no dipping the ball to your knees.'], drills: ['d-closeout-footwork', 'd-relocation'] },
    { t: 'Take it to game speed', m: 15, pts: ['Shoot at the speed you will play at. Slow practice shots do not transfer.', 'Add movement and fatigue once your form holds for 10 in a row.', 'Track every attempt in Shot Lab so you see real percentages, not feelings.'], drills: ['d-movement-3s'] },
  ] },
  { id: 'handle', title: 'Handle Under Pressure', area: 'Ball Handling', color: '#e9d98d', blurb: 'Keep your dribble alive against real pressure.', lessons: [
    { t: 'Pound it low', m: 8, pts: ['A hard dribble comes back faster, so the defender has less time to poke it.', 'Below the knee when you are guarded, waist-high only in the open floor.', 'Eyes up: you cannot read the defense staring at the ball.'], drills: ['d-pound-series'] },
    { t: 'The weak hand', m: 10, pts: ['Defenses will force you left (or right). Your weak hand decides how good you are.', 'Two-ball work makes the weak hand keep up with the strong one.', 'Spend twice as many reps on the weak hand until they feel the same.'], drills: ['d-two-ball', 'd-spider'] },
    { t: 'Change of pace beats change of direction', m: 10, pts: ['Most defenders can mirror a crossover. Few can handle stop-and-go.', 'The hesitation works because of the burst after it.', 'Sell it with your eyes and shoulders, not by bouncing the ball higher.'], drills: ['d-hesi-drive'] },
    { t: 'Escaping traps and pressure', m: 10, pts: ['Retreat dribble to buy space; do not turn your back fully.', 'Protect with the off arm (bar arm) without pushing off.', 'Never pick up the dribble in the corner against two defenders.'], drills: ['d-retreat-attack'] },
    { t: 'Moves with a purpose', m: 12, pts: ['Every move should gain an angle toward the rim, not just look good.', 'Two moves max, then attack or pass.', 'Finish every handling rep with a shot or layup so it connects to scoring.'], drills: ['d-cone-weave', 'd-full-court-cod'] },
  ] },
  { id: 'finish', title: 'Finishing Package', area: 'Finishing', color: '#55c98b', blurb: 'Score at the rim through length and contact.', lessons: [
    { t: 'Two-foot power', m: 8, pts: ['A two-foot gather gives you balance through contact.', 'Ball stays high and protected on the way up.', 'Finish through the defender’s body, not away from it.'], drills: ['d-two-foot-power'] },
    { t: 'Use the glass', m: 8, pts: ['From the side, the backboard is a bigger target than the rim.', 'Aim for the top corner of the square.', 'Inside hand on the near side, outside hand to protect on the far side.'], drills: ['d-inside-hand-glass', 'd-outside-hand-both'] },
    { t: 'Change the angle', m: 10, pts: ['Euro-step: wide second step, ball moves with the step.', 'Reverse: use the rim to shield the ball from the shot blocker.', 'Up-and-under: sell the fake with the ball up high.'], drills: ['d-euro-footwork', 'd-reverse-finish', 'd-up-and-under'] },
    { t: 'The floater', m: 10, pts: ['Your answer to a big who sits at the rim.', 'Release early and high, off one or two feet, soft wrist.', 'Practice from 6 to 12 feet on both sides.'], drills: ['d-floater-ladder'] },
    { t: 'Finish tired', m: 10, pts: ['Most missed layups in games happen late, when legs are gone.', 'Train finishes at the end of conditioning, not only fresh.', 'Same form on the last layup as the first.'], drills: ['d-full-court-layups'] },
  ] },
  { id: 'pnr', title: 'Guard IQ: Reading Ball Screens', area: 'Pick-and-Roll', color: '#8db8de', blurb: 'Make the right read off every screen.', lessons: [
    { t: 'Set it up', m: 8, pts: ['Wait for the screen to be set: leaving early gets your screener called for a moving pick.', 'Set your defender up a step the other way first.', 'Come off shoulder to hip so no one fits between you and the screener.'], drills: ['d-chair-pnr'] },
    { t: 'Read the big', m: 10, pts: ['Big drops back: pull-up or floater in the space in front of him.', 'Big hedges or shows high: split, or hit the roller behind him.', 'Big switches: attack his feet before help arrives, or reset for a mismatch.'], drills: ['d-chair-pnr'] },
    { t: 'Read your defender', m: 10, pts: ['Goes over the top: turn the corner downhill.', 'Goes under: pull up behind the screen.', 'Jumps it early: reject the screen and go the other way.'], drills: ['d-chair-pnr', 'd-read-cards'] },
    { t: 'Snake and keep your dribble', m: 8, pts: ['Snake back across the screen to freeze the big in drop.', 'Keep the defender on your back with your body.', 'The pull-up and the pocket pass come from the same look.'], drills: ['d-chair-pnr'] },
    { t: 'React, don’t script', m: 10, pts: ['Good guards decide on the second dribble off the screen.', 'Practice reads with random cues, not a set move.', 'Watch your own film and pause at the screen: what did the big do?'], drills: ['d-read-cards'] },
  ] },
  { id: 'mind', title: 'Mental Game: Next Play', area: 'Game Situations', color: '#f5c154', blurb: 'Seven days to a steadier mindset in games.', lessons: [
    { t: 'Day 1: Next play', m: 5, pts: ['The last play is over. Pick one word to reset (like "next") and say it after mistakes.', 'Today: in practice, say your word after every miss and move on.'], drills: [] },
    { t: 'Day 2: Breathe before free throws', m: 5, pts: ['Slow breath in for 4, out for 6 before every free throw.', 'Build the same routine every single time.'], drills: ['d-pressure-fts'] },
    { t: 'Day 3: Control the controllables', m: 5, pts: ['You control effort, attitude, preparation and body language.', 'You do not control refs, minutes or the score. Let them go.'], drills: [] },
    { t: 'Day 4: Visualize', m: 5, pts: ['Before bed, picture five makes from your favorite spots in detail: sound, feel, net.', 'Then picture handling a mistake calmly and getting back on defense.'], drills: [] },
    { t: 'Day 5: Pressure reps', m: 10, pts: ['Add a consequence to practice shots so pressure feels normal.', 'Track pressure free throws vs normal ones in Shot Lab.'], drills: ['d-pressure-fts', 'd-late-clock'] },
    { t: 'Day 6: Body language', m: 5, pts: ['Coaches watch what you do after a mistake more than the mistake.', 'Head up, sprint back, talk on defense.'], drills: [] },
    { t: 'Day 7: Your game plan', m: 5, pts: ['Write three things you will do in the next game no matter what (example: sprint back, talk on defense, attack the first closeout).', 'Review them before tip-off.'], drills: [] },
  ] },
];
